def dedupe_contacts(rows):
    """Deduplicate CRM contact rows into one dict per person.

    Standard library only. See the rules from the data team for details.
    """

    DIGITS = "0123456789"
    GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}

    def get(row, key):
        v = row.get(key)
        return v if v is not None else ""

    def normalize_email(raw):
        email = raw.strip().lower()
        if email.count("@") == 1:
            local, domain = email.split("@")
            if domain in GMAIL_DOMAINS:
                local = local.replace(".", "")
                local = local.split("+", 1)[0]
                domain = "gmail.com"
            email = local + "@" + domain
        return email

    def email_is_valid(email):
        if email.count("@") != 1:
            return False
        local, domain = email.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def normalize_phone(raw):
        digits = "".join(c for c in raw if c in DIGITS)
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        return digits

    # Step 1: normalize and filter rows (keeping original input order).
    recs = []
    for row in rows:
        email = normalize_email(get(row, "email"))
        email = email if email_is_valid(email) else ""
        phone = normalize_phone(get(row, "phone"))
        phone = phone if len(phone) == 10 else ""
        if not email and not phone:
            continue
        recs.append({
            "row": row,
            "email": email,
            "phone": phone,
            "last_key": get(row, "last_name").strip().lower(),
        })

    n = len(recs)

    # Step 2: union-find for transitive matching.
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # Keep the smaller index as root (earliest row).
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    seen_email = {}
    seen_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in seen_email:
                union(i, seen_email[r["email"]])
            else:
                seen_email[r["email"]] = i
        if r["phone"] and r["last_key"]:
            key = (r["phone"], r["last_key"])
            if key in seen_phone_last:
                union(i, seen_phone_last[key])
            else:
                seen_phone_last[key] = i

    # Step 3: collect groups; indices are appended in input order.
    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    # Step 4: build output, ordered by each group's earliest row.
    result = []
    for root in sorted(groups, key=lambda r: min(groups[r])):
        members = groups[root]  # ascending input order

        # Most recent first; reverse sort is stable, so ties keep input order.
        by_recency = sorted(
            members,
            key=lambda i: get(recs[i]["row"], "updated"),
            reverse=True,
        )

        def pick_text(field):
            for i in by_recency:
                v = get(recs[i]["row"], field).strip()
                if v:
                    return v
            return ""

        email = ""
        for i in by_recency:
            if recs[i]["email"]:
                email = recs[i]["email"]
                break

        phone = ""
        for i in by_recency:
            if recs[i]["phone"]:
                phone = recs[i]["phone"]
                break

        tags = set()
        for i in members:
            for t in get(recs[i]["row"], "tags").split(";"):
                t = t.strip().lower()
                if t:
                    tags.add(t)

        opted_out = "N"
        for i in members:
            if get(recs[i]["row"], "opted_out").strip().upper() == "Y":
                opted_out = "Y"
                break

        result.append({
            "first_name": pick_text("first_name"),
            "last_name": pick_text("last_name"),
            "email": email,
            "phone": phone,
            "zip": pick_text("zip"),
            "tags": ";".join(sorted(tags)),
            "opted_out": opted_out,
            "updated": max(get(recs[i]["row"], "updated") for i in members),
        })

    return result
```

Some notes:

- **Opt-outs:** Because of rule 4, a row with no valid email and no valid phone is dropped before matching, so its `opted_out` value is ignored. Such a row has no usable email, so it can't affect who receives the send. A row with a bad email but a valid phone is kept and can still pass an opt-out to its group.
- **Before sending:** Filter the output to `opted_out == "N"` and a non-empty `email`. People who matched only by phone, or whose only valid contact is a phone, will have `email == ""`.
- **Dates:** `updated` is compared as a string, which is correct for ISO dates like `2026-10-02`.
- **Testing:** I haven't run this against your export. Spot-check a few known duplicate clusters, especially Gmail dot/plus variants and phone-plus-last-name matches, before the send.
